import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.Cu3jFwFD.js";const p=JSON.parse(`{"title":"Boss day: Charon's soul race","description":"","frontmatter":{},"headers":[],"relativePath":"features/boss-charon/design.md","filePath":"features/boss-charon/design.md","lastUpdated":1794907169000}`),r={name:"features/boss-charon/design.md"};function i(o,a,d,l,h,u){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="boss-day-charon-s-soul-race" tabindex="-1">Boss day: Charon&#39;s soul race <a class="header-anchor" href="#boss-day-charon-s-soul-race" aria-label="Permalink to &quot;Boss day: Charon&#39;s soul race&quot;">​</a></h1><p><strong>Status:</strong> <span class="status-badge status-designed">DESIGNED</span> · <strong>Updated:</strong> 2026-11-17 · <a href="./../../GDD">GDD</a></p><p>If the run quota is met after Day 3, Day 4 is Charon&#39;s day. Instead of a profit quota, Hermes races Iris Express to deliver 12 souls. Iris is only a score on a bar: she has no van. First to 12 ends the day. Serves <strong>Push your luck</strong> (the race rewards fast, clean deliveries over detours) and gives the run its own climax.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ol><li>Played only after a successful Day 3 (<a href="./../run-and-quota/design">run-and-quota</a>). Before it, a banner announces the boss day in the Garage; the race and its short dialogue (Charon, Iris, Charon) play on the map.</li><li>Only Safe packages spawn on the boss day, shown as souls; no Zeus and no Chance (scam) jobs (<a class="decision-ref" href="/hex-gdd/GDD#d-066">D‑066</a>). Every delivery is 1 soul. HP carries over from Day 3; the lightning shield and nitro work as usual. Shift lightning uses the danger 1 setup (lightning areas only), drawn blue. Iris gains a soul after a random interval, now and then in a quick chain.</li><li>Iris&#39;s pace has a rubber band: each soul Hermes is ahead of her makes her slightly faster, each soul behind slightly slower, within limits.</li><li>First to 12 souls wins and the day ends. If the shift clock runs out first, or the van is wrecked, Iris wins. HQ does nothing on the boss day.<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>irisTimer starts at random(5, 7)</span></span>
<span class="line"><span>each frame: irisTimer -= dt</span></span>
<span class="line"><span>when irisTimer &lt;= 0: iris += 1</span></span>
<span class="line"><span>    lead = hermes - iris</span></span>
<span class="line"><span>    irisTimer = (random() &lt; 0.12) ? 0.6</span></span>
<span class="line"><span>              : random(5.5, 8) * clamp(1 - 0.06 * lead, 0.6, 1.25)</span></span></code></pre></div></li><li>Hermes winning ends the run on the ending scene (four lines of dialogue, then &quot;TO BE CONTINUED...&quot;). Iris winning is game over (<a href="./../run-and-quota/design">run-and-quota</a>).</li><li>The boss day has no overtime and no money quota; income does not matter.</li><li>Lightning on the boss day is blue (visual only).</li></ol><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Value</th><th>Unit</th><th>What to watch in playtests</th></tr></thead><tbody><tr><td>Soul target</td><td>12</td><td>souls</td><td></td></tr><tr><td>Boss shift length</td><td>120</td><td>s</td><td>Enough room for 12 deliveries</td></tr><tr><td>Iris first soul</td><td>5–7</td><td>s</td><td></td></tr><tr><td>Iris interval</td><td>5.5–8</td><td>s</td><td>A strong player with no upgrades only just wins</td></tr><tr><td>Iris chain chance</td><td>12</td><td>%</td><td></td></tr><tr><td>Iris chain delay</td><td>0.6</td><td>s</td><td></td></tr><tr><td>Rubber band per soul ahead/behind</td><td>0.06</td><td>factor</td><td></td></tr><tr><td>Rubber band limits</td><td>0.6–1.25</td><td>factor</td><td></td></tr></tbody></table><h2 id="edge-cases" tabindex="-1">Edge cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge cases&quot;">​</a></h2><ul><li>A scam delivery that fails gives no soul.</li><li>Both players cannot reach 12 at once; the first event decides.</li><li>Pausing freezes Iris.</li></ul><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ul><li><mark class="tune">TUNE</mark> All numbers are the prototype&#39;s.</li><li>The Iris race may be too easy once cards are strong; watch win rate by upgrades owned.</li></ul><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><ul><li>2026-11-17: designed from the prototype. New since the old GDD (it only had &quot;teaser region berikutnya&quot; after Day 7). Gated by <a class="decision-ref" href="/hex-gdd/GDD#d-025">D‑025</a>.</li></ul>`,13)])])}const g=e(r,[["render",i]]);export{p as __pageData,g as default};
